'use strict';const fs=require('fs'),vm=require('vm'),assert=require('assert/strict');const html=fs.readFileSync(__dirname+'/world.html','utf8'),src=html.match(/<script id="world-engine">([\s\S]*?)<\/script>/)[1],context={};context.globalThis=context;vm.runInNewContext(src,context);const E=context.WorldRules;
function key(s){return [s.player.x,s.player.y,s.collected,s.fluid,s.grip,s.stage,s.anchor?.x,s.anchor?.y,s.anchorUsed].join(',');}function solve(level,allowPower=true,challenge=false){const first=E.create(level,challenge),q=[{s:first,path:[]}],seen=new Set([key(first)]);for(let i=0;i<q.length;i++){const {s,path}=q[i];if(s.won)return path;for(const a of ['up','down','left','right',...(allowPower?['power','phase']:[])]){const n=JSON.parse(JSON.stringify(s));n.history=[];if(!E.act(n,a))continue;const k=key(n);if(!seen.has(k)){seen.add(k);q.push({s:n,path:[...path,a]});}}}return null;}
