// Level 4 needs both opening a route AND rebuilding a stopping point.
function constrained(level,permit,challenge=false){const q=[{s:E.create(level,challenge),n:0}],seen=new Set();for(let i=0;i<q.length;i++){const {s,n}=q[i];if(s.won)return true;for(const cmd of ['up','down','left','right','power','phase']){if(!permit(s,cmd,n))continue;const next=JSON.parse(JSON.stringify(s));next.history=[];if(!E.act(next,cmd))continue;const nn=n+(cmd==='power'?1:0),k=key(next)+','+Math.min(nn,8);if(!seen.has(k)){seen.add(k);q.push({s:next,n:nn});}}}return false;}
